import React from 'react';

const QuanLyThongBao = () => {
    return (
        <div style={styles.chatGrid}>
            {/* Cột 1: Mọi người */}
            <div className="glass-card fade-in" style={styles.chatPanel}>
                <div style={styles.panelHeader}>
                    <span style={styles.tabActive}>Mọi người</span>
                </div>
                <div style={{...styles.chatBody, backgroundImage: "url('../assets/nen_khung_chat.jpg')"}}>
                    {/* Tin nhắn mẫu */}
                    <div style={styles.msgLeft}>
                        <div style={styles.avatarMini}>105</div>
                        <div style={styles.bubble}>Mọi người ơi cho hỏi...</div>
                    </div>
                </div>
                <div style={styles.inputBox}>
                    <input style={styles.input} placeholder="Nhập tin nhắn chung..." />
                </div>
            </div>

            {/* Cột 2: Gửi riêng */}
            <div className="glass-card fade-in" style={styles.chatPanel}>
                <div style={{...styles.panelHeader, justifyContent: 'flex-end'}}>
                    <span style={{...styles.tabActive, backgroundColor: '#8b5e5e'}}>Gửi riêng</span>
                </div>
                <div style={styles.privateArea}>
                    {/* Danh sách phòng */}
                    <div style={styles.roomList}>
                        {['101', '102', '103', '104', '201'].map(id => (
                            <div key={id} className="room-circle">{id}</div>
                        ))}
                    </div>
                    {/* Chat riêng */}
                    <div style={styles.privateChat}>
                        <p style={{color: '#999', fontSize: '13px'}}>Chọn một cư dân để nhắn tin riêng</p>
                    </div>
                </div>
            </div>
        </div>
    );
};

const styles = {
    chatGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', height: '100%' },
    chatPanel: { display: 'flex', flexDirection: 'column', overflow: 'hidden' },
    panelHeader: { padding: '20px', display: 'flex' },
    tabActive: { backgroundColor: '#333', color: '#fff', padding: '8px 25px', borderRadius: '20px', fontSize: '13px', fontWeight: 'bold' },
    chatBody: { flex: 1, margin: '0 20px', backgroundSize: 'cover', borderRadius: '20px', padding: '20px' },
    inputBox: { padding: '20px' },
    input: { width: '100%', padding: '12px 20px', borderRadius: '15px', border: '1px solid #ddd', outline: 'none' },
    privateArea: { flex: 1, display: 'flex', padding: '0 20px 20px 20px', gap: '15px' },
    roomList: { width: '100px', display: 'flex', flexWrap: 'wrap', gap: '8px', alignContent: 'flex-start' },
    privateChat: { flex: 1, borderLeft: '1px solid #eee', display: 'flex', justifyContent: 'center', alignItems: 'center' }
};

export default QuanLyThongBao;
